package com.interview.fraud.casework;
import com.interview.fraud.platform.*; import com.interview.fraud.risk.FraudRuleEngine; import com.interview.fraud.transaction.*; import java.time.Instant; import java.util.*; import org.springframework.dao.DuplicateKeyException; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CaseWorkflowService {private final TransactionRepository transactions;private final CaseRepository cases;private final FraudRuleEngine rules;private final JdbcTemplate jdbc;private final AuditService audit;private final OutboxService outbox;public CaseWorkflowService(TransactionRepository t,CaseRepository c,FraudRuleEngine r,JdbcTemplate j,AuditService a,OutboxService o){transactions=t;cases=c;rules=r;jdbc=j;audit=a;outbox=o;}
 @Transactional public CaseView ingest(TransactionRequest request,String key,String actor){var existing=transactions.findByExternalId(request.transactionId());if(existing.isPresent())return CaseView.from(cases.findAll().stream().filter(c->c.transaction.id.equals(existing.get().id)).findFirst().orElseThrow());TransactionEntity t=transactions.saveAndFlush(new TransactionEntity(request));var evaluation=rules.evaluate(t,transactions.countByCustomerId(t.customerId));CaseEntity c=cases.saveAndFlush(new CaseEntity(t,evaluation.score()));for(var s:evaluation.signals())jdbc.update("INSERT INTO risk_signals(id,case_id,code,weight,description) VALUES(?,?,?,?,?)",UUID.randomUUID(),c.id,s.code(),s.weight(),s.description());jdbc.update("INSERT INTO idempotency_keys(idempotency_key,response_ref,created_at) VALUES(?,?,?)",key,c.caseNumber,Instant.now());audit.log(actor,"TRANSACTION_INGESTED","CASE",c.id.toString(),"transaction="+t.externalId);outbox.add("CASE",c.id.toString(),"CaseCreated",c.caseNumber);return CaseView.from(c);}
 public List<CaseView> list(){return cases.findAllByOrderByCreatedAtDesc().stream().map(CaseView::from).toList();} public CaseEntity require(UUID id){return cases.findById(id).orElseThrow();} public List<Map<String,Object>> signals(UUID id){return jdbc.queryForList("SELECT code,weight,description FROM risk_signals WHERE case_id=? ORDER BY weight DESC",id);}
 @Transactional public CaseView approve(UUID id,String action,String rationale,String actor,long expectedVersion){CaseEntity c=require(id);if(c.version!=expectedVersion)throw new IllegalStateException("Case was updated by another analyst");c.approvedAction=action;c.status="APPROVED";c.updatedAt=Instant.now();jdbc.update("INSERT INTO decisions(id,case_id,action,approved_by,rationale,created_at) VALUES(?,?,?,?,?,?)",UUID.randomUUID(),id,action,actor,rationale,Instant.now());audit.log(actor,"SENSITIVE_ACTION_APPROVED","CASE",id.toString(),action);outbox.add("CASE",id.toString(),"CaseActionApproved",action);return CaseView.from(cases.save(c));}}
